import{_ as i,l as r,o as e,c as l,v as t,p as s,x as o,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"交易速度与市场质量","description":"","frontmatter":{"title":"交易速度与市场质量","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/speed-market-quality.md","filePath":"quant/speed-market-quality.md","lastUpdated":1789023840000}'),E={name:"quant/speed-market-quality.md"};function B(u,a,h,m,_,A){const n=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="交易速度与市场质量" tabindex="-1">交易速度与市场质量 <a class="header-anchor" href="#交易速度与市场质量" aria-label="Permalink to &quot;交易速度与市场质量&quot;">​</a></h1><div class="epigraph"><p>把整个市场变快，不等于把每笔交易的延迟差消灭。质量取决于相对速度如何被协议处理：发现可以加快，价差与深度却可以因竞赛与撤退而变差。</p><footer>—— Pagnotta and Philippon, Competing on Speed, American Economic Review, 2018；算法交易与流动性见 Hendershott, Jones and Menkveld, Journal of Finance, 2011</footer></div><p><a href="/quant/microstructure-invariance">不变量</a>给出跨品种缩放。缺口是政策变量「速度」本身：交易所升级、托管、取消地板，市场质量如何变。Pagnotta 与 Philippon（2018）把场所之间的速度竞争写成均衡；HJM（2011）提供算法交易改善流动性的证据。本课收束高频单元：质量是多指标，速度不是单调的善。然后交给市场设计续，从订单类型与场所规则动手。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>市场质量至少包括：价差、深度、实现冲击、价格发现（Hasbrouck 误差、VR）、波动螺旋的脆弱性、以及分配（谁付速度税）。绝对延迟下降（所有人快 10 微秒）若保持相对排序，狙击期权 \\(s\\) 仍在，竞赛投入可能不变甚至因交易更密而增加。相对延迟下降（随机化、批量、颠簸）才砍 \\(s\\)。问题是经验里看到的「变快」多是哪一种：托管是相对速度的军备；自动报价更多是处理成本下降。</p><p>HJM 的流动性改善，更接近处理成本与做市自动化（Stoll 三项里的第一项），不是 BCS 竞赛被解决。两篇文献必须同时读，才能避免「HFT 提高质量」或「HFT 破坏质量」的单句。</p><h3 id="场所竞争加速" tabindex="-1">场所竞争加速 <a class="header-anchor" href="#场所竞争加速" aria-label="Permalink to &quot;场所竞争加速&quot;">​</a></h3><p>Pagnotta–Philippon：投资者喜欢快的场所，场所投资速度吸引流，碎片化下可能过度投资速度。这与交易所之间的 make-take、tick 竞争并列。速度成为垂直差异化：对延迟敏感的流去托管场所，不敏感的流留在慢所或暗池。透明与匿名课的场所转移，在此多了延迟维度。</p><p><span class="marginnote">Boehmer、Fong 与 Wu 等跨国证据表明算法交易对流动性的符号随环境变。本课不报一个全球系数，只保留：符号取决于相对速度与供给是否撤退。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把质量指标对速度冲击回归：自动报价引入、光纤开通、主机托管、国际链路。必须分开短窗新闻质量与全日平均价差。发现用 Hasbrouck 长期乘数或定价误差；流动性用有效价差与深度；脆弱性用压力窗撤退。若发现改善而压力脆弱性升，政策含义不同于双改善。</p><p>理论基准：Biais–Foucault–Moinas 的均衡快速交易；BCS 的竞赛耗散。把「平均延迟」当处理变量会混淆绝对与相对。</p>',12)),(e(),s(c,null,{default:o(()=>[d(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20Abs%5B%22%E7%BB%9D%E5%AF%B9%E5%BB%B6%E8%BF%9F%E4%B8%8B%E9%99%8D%22%5D%20--%3E%20Proc%5B%22%E5%A4%84%E7%90%86%E6%88%90%E6%9C%AC%20%2F%20%E5%81%9A%E5%B8%82%E8%87%AA%E5%8A%A8%E5%8C%96%22%5D%0A%20%20Rel%5B%22%E7%9B%B8%E5%AF%B9%E5%BB%B6%E8%BF%9F%E4%BB%8D%E5%9C%A8%22%5D%20--%3E%20Race%5B%22%E7%8B%99%E5%87%BB%E6%9C%9F%E6%9D%83%20s%22%5D%0A%20%20Proc%20--%3E%20Qplus%5B%22%E5%B9%B3%E9%9D%99%E6%9C%9F%E4%BB%B7%E5%B7%AE%E4%B8%8B%E9%99%8D%22%5D%0A%20%20Race%20--%3E%20Qminus%5B%22%E9%80%9F%E5%BA%A6%E7%A8%8E%E4%B8%8E%E8%84%86%E5%BC%B1%E6%80%A7%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>平静期：自动化做市压低处理与库存成本，Menkveld 画像主导，质量升。新闻期：相对速度主导，Foucault–Hombert–Roşu 的发现腿与被捡同时升。压力期：反馈螺旋，速度加快的是空簿路径而不是补给。同一技术栈三态三色。市场设计续的 peg、颠簸、收盘竞价、熔断，都是在三态上切不同的刀，而不是「把市场再加速一点」。</p><p>对执行：平均质量改善不降低你在新闻窗的被捡。算法必须状态依赖，这与限价/市价阈值课一致。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>「速度」在数据里常是代理（消息率、托管虚拟变量），不是毫秒。跨国制度差（涨跌停、印花税）会淹没速度效应。把质量写成单一指数（再对政策回归）会让发现与流动性互相抵消或双计。本课结束高频理论单元；具体规则从下一课 peg 与 D-limit 开始，不再抽象谈速度。</p><p><span class="marginnote">投资者保护若只看平均有效价差，会批准一切能压低平静期价差的加速，忽视分配与尾部。指标要分状态报告。</span></p><p>市场设计续从订单与场所规则动手：peg、颠簸、收盘拍卖、匹配算法，都是在三态上切一刀，而不是再把全市场的平均延迟削短一点。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>绝对变快主要降处理成本；相对速度决定狙击租金。质量必须分平静、新闻、压力三态。</li><li>场所之间竞速可能过度投资延迟，碎片化放大。</li><li>HJM 式流动性改善与 BCS 式竞赛可以并存，单句评价 HFT 不够。</li><li>出处：Pagnotta and Philippon, <em>American Economic Review</em>, 2018；Hendershott, Jones and Menkveld, <em>Journal of Finance</em>, 2011。</li></ul>',9))])}const P=i(E,[["render",B]]);export{k as __pageData,P as default};
